import ast, sys

# Check for 'self' usage outside class methods in groupchat
files = [
    '/root/nanobot-src/nanobot/groupchat/orchestra/broadcast.py',
    '/root/nanobot-src/nanobot/groupchat/orchestra/engine.py',
    '/root/nanobot-src/nanobot/groupchat/orchestra/tools/chatroom_tools.py',
    '/root/nanobot-src/nanobot/groupchat/orchestra/tools/tool_loop.py',
    '/root/nanobot-src/nanobot/groupchat/orchestra/mailbox.py',
]

for f in files:
    try:
        with open(f) as fh:
            tree = ast.parse(fh.read())
        # Find top-level functions (not inside classes)
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef) and not any(
                isinstance(parent, ast.ClassDef) 
                for parent in ast.walk(tree) if hasattr(parent, 'body') and node in parent.body
            ):
                # Check if 'self' is used in this function
                source_lines = open(f).readlines()
                for child in ast.walk(node):
                    if isinstance(child, ast.Name) and child.id == 'self':
                        print(f'{f}:{node.lineno} - top-level function \"{node.name}\" uses self')
                        break
    except Exception as e:
        print(f'Error parsing {f}: {e}')
